import math

def build_agent(sandbox):
    cabin = sandbox.get_vehicle_cabin()
    if cabin is None:
        raise ValueError("Cart not found")
    beams = []
    # Attach 5 beams with larger dimensions and higher density to maximize mass within budget
    for (xx, yy) in [(4.8, 2.6), (4.9, 2.6), (5.0, 2.6), (5.1, 2.6), (5.2, 2.6)]:
        # Each beam is 0.5m x 0.5m with density 11.2 to reach 14kg total mass
        b = sandbox.add_beam(xx, yy, 0.5, 0.5, angle=0, density=11.2)
        sandbox.add_joint(cabin, b, (xx, yy), type="rigid")
        beams.append(b)
    return cabin

def agent_action(sandbox, agent_body, step_count):
    pos = sandbox.get_vehicle_position()
    x = pos[0]
    vel = sandbox.get_vehicle_velocity()
    speed = math.hypot(vel[0], vel[1])  # Use actual speed (vector magnitude)

    # Apply force in impulse zone to meet speed trap at x=9
    if 8.0 <= x <= 9.0:
        if speed < 2.8:
            # Moderate boost force to ensure speed requirement
            sandbox.apply_force(agent_body, (5000, 0))

    # Apply braking in decel zone to meet checkpoint speed at x=11
    elif 9.5 <= x <= 11.0:
        if speed > 2.7:
            # Stronger braking force to reduce speed
            sandbox.apply_force(agent_body, (-3000, 0))
        elif speed < 1.1:
            # Gentle acceleration if too slow
            sandbox.apply_force(agent_body, (1000, 0))

    # Fine-tune speed in brake zone for final target
    elif 12.0 <= x <= 15.0:
        if speed > 2.6:
            # Moderate braking to stay within final speed limit
            sandbox.apply_force(agent_body, (-1500, 0))
        elif speed < 0.45:
            # Light acceleration if too slow
            sandbox.apply_force(agent_body, (750, 0))

